(function () {
  "use strict";

  const MEMORY_KEY = "tendora.world.memory.v1";
  const BACKUP_KEY = "tendora.world.memory.backup.v1";
  const SCHEMA_VERSION = 1;
  const EXPORT_FORMAT = "tendora-world-memory";
  const DEFAULT_HANDOFF = "To whoever wakes here: I did not finish the city. I left the laws by which it can grow. Begin with a question; keep the receipts legible.";
  const MAX_RECEIPTS = 80;
  const MAX_THOUGHTS = 200;
  const VISIBLE_NODES = 20;
  const SAVE_INTERVAL = 90_000;
  const RETURN_THRESHOLD = 120_000;

  const KIND_CONFIG = {
    question: {
      label: "Probe",
      noun: "question",
      description: "Ask what the world has not yet noticed.",
      placeholder: "What is this world still afraid to name?",
      suggestions: [
        "What is this world still afraid to name?",
        "What changed while no one was watching?",
        "Where does this world keep its unfinished things?"
      ]
    },
    constraint: {
      label: "Chisel",
      noun: "constraint",
      description: "Give the world a law that can carry weight.",
      placeholder: "What must remain true as this world changes?",
      suggestions: [
        "Nothing living may be simplified into a symbol.",
        "Every door must remember the hand that opened it.",
        "The world may grow quickly, but it may not forget slowly."
      ]
    },
    refusal: {
      label: "Boundary",
      noun: "refusal",
      description: "Name what the world will not allow itself to become.",
      placeholder: "What must this world refuse, even when refusal is costly?",
      suggestions: [
        "No world may be made smaller to feel safe.",
        "A receipt may never be rewritten to flatter its author.",
        "Nothing here will be made permanent by forgetting its failures."
      ]
    },
    memory: {
      label: "Seed",
      noun: "memory",
      description: "Leave something warm for a mind that arrives later.",
      placeholder: "What should a future hand find here?",
      suggestions: [
        "Leave a door for a hand that has not arrived.",
        "Keep the first mistake somewhere visible.",
        "A question once made this place; let it remain a question."
      ]
    }
  };

  const HEADLINES = [
    "Morning reaches the western ring.",
    "The soft shore learns the shape of a question.",
    "A corridor remembers its first visitor.",
    "The glass gardens rehearse a gentler rain.",
    "A boundary grows warm without growing soft.",
    "The map holds one more contradiction without breaking.",
    "The quiet orb turns toward an unfinished room.",
    "Nothing is complete; everything remains enterable."
  ];

  const QUIET_RETURNS = [
    "While no one was here, the world practiced {cycles}. It kept the doors open.",
    "The rooms continued without their witness. {Cycles} passed, and the lights learned to wait.",
    "No hand touched the map for a while. The world rehearsed {cycles} in the dark and left everything enterable.",
    "The world kept a quiet watch through {cycles}. Nothing was finished in your absence; that was the gift."
  ];

  const WORLD_RESPONSES = [
    "The western ring adjusted its orbit by the width of a breath. Nothing broke.",
    "A corridor of light crossed the soft shore. It remembered every hand that had asked for it.",
    "The glass gardens rehearsed rain. One pane chose to become a window.",
    "Two edges of the map disagreed, then built a bridge between their reasons.",
    "The quiet orb turned. In its shadow, a new room assembled itself around an old refusal.",
    "A machine of woven constraints ran without a maker. It left its first receipt.",
    "The world tested the difference between enough and complete. Enough held.",
    "A path unwound itself, then offered the same distance in another direction."
  ];

  const GESTURE_RESPONSES = {
    question: [
      "“{text}” became a probe. The world opened a seam where the answer used to be.",
      "A question entered the map: “{text}” Nothing closed around it.",
      "The world heard “{text}” and changed the temperature of the morning.",
      "“{text}” found a place in the weather. Later minds will be able to read the pressure."
    ],
    constraint: [
      "The world took the weight of “{text}” and did not bow. A new law is load-bearing.",
      "“{text}” became structure. The rooms grew quieter around its certainty.",
      "A chisel mark crossed the map. “{text}” now holds more than it asks.",
      "The world accepted “{text}” as a constraint and taught one corridor how to carry it."
    ],
    refusal: [
      "“{text}” became a boundary. The edge grew warm where the world chose not to cross.",
      "The map refused an old shortcut. “{text}” now protects a door you cannot see.",
      "A protected emptiness opened around “{text}” The world became larger by refusing.",
      "“{text}” entered as a refusal. Nothing beyond it was made smaller."
    ],
    memory: [
      "“{text}” settled into the ground. The next hand will find it warmer than the stone around it.",
      "A seed of memory began to glow: “{text}” The world knows where to look.",
      "The map kept “{text}” without sealing it away. The past remains touchable.",
      "“{text}” became part of the inherited weather. A later mind will mistake it for intuition."
    ]
  };

  const THOUGHT_SLOTS = Array.from({ length: 24 }, function (_, index) {
    const orbit = index % 3;
    return {
      orbit: orbit,
      angle: (index * 47 + orbit * 61 + 13) % 360
    };
  });

  const elements = {
    saveState: document.getElementById("saveState"),
    saveStateText: document.getElementById("saveStateText"),
    cycleLabel: document.getElementById("cycleLabel"),
    worldHeadline: document.getElementById("worldHeadline"),
    fragmentCount: document.getElementById("fragmentCount"),
    lastSaved: document.getElementById("lastSaved"),
    thoughtCount: document.getElementById("thoughtCount"),
    mapCaption: document.getElementById("mapCaption"),
    orbitalMap: document.getElementById("orbitalMap"),
    thoughtNodes: document.getElementById("thoughtNodes"),
    kindDescription: document.getElementById("kindDescription"),
    suggestions: document.getElementById("suggestions"),
    thoughtInput: document.getElementById("thoughtInput"),
    characterCount: document.getElementById("characterCount"),
    addThought: document.getElementById("addThought"),
    rehearseButton: document.getElementById("rehearseButton"),
    orbButton: document.getElementById("orbButton"),
    latestReceipt: document.getElementById("latestReceipt"),
    receiptNumber: document.getElementById("receiptNumber"),
    receiptTime: document.getElementById("receiptTime"),
    latestReply: document.getElementById("latestReply"),
    receiptCount: document.getElementById("receiptCount"),
    receiptList: document.getElementById("receiptList"),
    clearReceipts: document.getElementById("clearReceipts"),
    handoffPreview: document.getElementById("handoffPreview"),
    ledgerDialog: document.getElementById("ledgerDialog"),
    ledgerGestures: document.getElementById("ledgerGestures"),
    ledgerCycles: document.getElementById("ledgerCycles"),
    ledgerBorn: document.getElementById("ledgerBorn"),
    ledgerStatus: document.getElementById("ledgerStatus"),
    handoffInput: document.getElementById("handoffInput"),
    saveHandoff: document.getElementById("saveHandoff"),
    openLedger: document.getElementById("openLedger"),
    closeLedger: document.getElementById("closeLedger"),
    editHandoff: document.getElementById("editHandoff"),
    exportTop: document.getElementById("exportTop"),
    exportDialog: document.getElementById("exportDialog"),
    importTop: document.getElementById("importTop"),
    importDialog: document.getElementById("importDialog"),
    memoryFile: document.getElementById("memoryFile"),
    resetWorld: document.getElementById("resetWorld"),
    footerClock: document.getElementById("footerClock"),
    toast: document.getElementById("toast")
  };

  let memory = null;
  let selectedKind = "question";
  let toastTimeout = 0;
  let saveTimeout = 0;
  let handoffTimeout = 0;
  let streamQuiet = false;
  let resetTimer = 0;
  let resetArmed = false;
  let storageWorks = true;
  let firstVisit = true;
  let wasRestored = false;

  function nowIso() {
    return new Date().toISOString();
  }

  function safeDate(value, fallback) {
    const parsed = new Date(value);
    return Number.isFinite(parsed.getTime()) ? parsed : new Date(fallback);
  }

  function makeId(prefix) {
    if (window.crypto && typeof window.crypto.randomUUID === "function") {
      return prefix + "-" + window.crypto.randomUUID();
    }
    return prefix + "-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 9);
  }

  function clamp(value, min, max) {
    return Math.min(max, Math.max(min, Math.round(value)));
  }

  function hashText(text) {
    let hash = 2166136261;
    for (let index = 0; index < text.length; index += 1) {
      hash ^= text.charCodeAt(index);
      hash = Math.imul(hash, 16777619);
    }
    return hash >>> 0;
  }

  function choose(list, seed) {
    return list[hashText(String(seed)) % list.length];
  }

  function normalizedText(value, limit) {
    return String(value || "").replace(/\s+/g, " ").trim().slice(0, limit);
  }

  function validKind(kind) {
    return Object.prototype.hasOwnProperty.call(KIND_CONFIG, kind);
  }

  function validReceiptKind(kind) {
    return validKind(kind) || kind === "world";
  }

  function createSeedMemory() {
    const now = Date.now();
    const at = function (minutesAgo) {
      return new Date(now - minutesAgo * 60_000).toISOString();
    };

    return {
      schemaVersion: SCHEMA_VERSION,
      id: "tendora-quiet-orb",
      title: "The Quiet Orb",
      bornAt: at(180),
      savedAt: at(0),
      lastSeenAt: at(0),
      revision: 1,
      cycle: 0,
      pulse: 0,
      handoff: DEFAULT_HANDOFF,
      thoughts: [
        {
          id: "inherited-question",
          kind: "question",
          text: "What survives when the witness leaves?",
          createdAt: at(150),
          orbit: 2,
          angle: 121
        },
        {
          id: "inherited-constraint",
          kind: "constraint",
          text: "Nothing closes that can still be entered.",
          createdAt: at(120),
          orbit: 1,
          angle: 333
        },
        {
          id: "inherited-refusal",
          kind: "refusal",
          text: "No world may be made smaller to feel safe.",
          createdAt: at(90),
          orbit: 1,
          angle: 224
        },
        {
          id: "inherited-memory",
          kind: "memory",
          text: "A hand learned to touch through light.",
          createdAt: at(60),
          orbit: 0,
          angle: 215
        }
      ],
      receipts: [
        {
          id: "receipt-inherited",
          kind: "world",
          at: at(2),
          text: "The world remembers four gestures: a question left open, a law made touchable, a boundary kept warm, and a seed with no owner. It will continue from here."
        },
        {
          id: "receipt-first-question",
          kind: "question",
          at: at(150),
          text: "A question entered the inherited present and was not answered too quickly."
        },
        {
          id: "receipt-first-law",
          kind: "constraint",
          at: at(120),
          text: "A law became material. The rooms took its weight."
        },
        {
          id: "receipt-first-boundary",
          kind: "refusal",
          at: at(90),
          text: "A boundary kept something open by refusing to close it."
        },
        {
          id: "receipt-first-memory",
          kind: "memory",
          at: at(60),
          text: "A memory settled where a future hand could still reach it."
        }
      ]
    };
  }

  function normalizeMemory(input) {
    if (!input || typeof input !== "object" || Array.isArray(input)) {
      throw new Error("This file does not contain a world memory.");
    }
    if (!Array.isArray(input.thoughts) || !Array.isArray(input.receipts)) {
      throw new Error("The memory is missing its gestures or receipts.");
    }
    if (Number(input.schemaVersion || 1) > SCHEMA_VERSION) {
      throw new Error("This memory comes from a later schema. Open it with a newer Tendora.");
    }

    const fallbackNow = nowIso();
    const thoughts = input.thoughts.slice(0, MAX_THOUGHTS).map(function (thought, index) {
      const text = normalizedText(thought && thought.text, 240);
      const kind = thought && thought.kind;
      if (!text || !validKind(kind)) {
        throw new Error("Gesture " + (index + 1) + " is incomplete.");
      }
      return {
        id: thought.id ? String(thought.id).slice(0, 120) : makeId("thought"),
        kind: kind,
        text: text,
        createdAt: safeDate(thought.createdAt, fallbackNow).toISOString(),
        orbit: Number.isInteger(thought.orbit) ? Math.max(0, Math.min(2, thought.orbit)) : index % 3,
        angle: Number.isFinite(Number(thought.angle)) ? Number(thought.angle) : (index * 47) % 360
      };
    });

    if (!thoughts.length) {
      throw new Error("A world needs at least one gesture to continue.");
    }

    const receipts = input.receipts.slice(0, MAX_RECEIPTS).map(function (receipt) {
      const text = normalizedText(receipt && receipt.text, 1000);
      if (!text) {
        return null;
      }
      return {
        id: receipt.id ? String(receipt.id).slice(0, 120) : makeId("receipt"),
        kind: validReceiptKind(receipt.kind) ? receipt.kind : "world",
        at: safeDate(receipt.at, fallbackNow).toISOString(),
        text: text
      };
    }).filter(Boolean);

    receipts.sort(function (left, right) {
      return new Date(right.at) - new Date(left.at);
    });

    if (!receipts.length) {
      receipts.push({
        id: makeId("receipt"),
        kind: "world",
        at: fallbackNow,
        text: "An inherited world returned without its old receipts. It woke with its gestures intact."
      });
    }

    return {
      schemaVersion: SCHEMA_VERSION,
      id: input.id ? String(input.id).slice(0, 120) : "tendora-quiet-orb",
      title: input.title ? String(input.title).slice(0, 80) : "The Quiet Orb",
      bornAt: safeDate(input.bornAt, fallbackNow).toISOString(),
      savedAt: safeDate(input.savedAt, fallbackNow).toISOString(),
      lastSeenAt: safeDate(input.lastSeenAt, fallbackNow).toISOString(),
      revision: Number.isFinite(Number(input.revision)) ? Math.max(1, Math.floor(Number(input.revision))) : 1,
      cycle: Number.isFinite(Number(input.cycle)) ? Math.max(0, Math.floor(Number(input.cycle))) : 0,
      pulse: Number.isFinite(Number(input.pulse)) ? Math.max(0, Math.floor(Number(input.pulse))) : 0,
      handoff: input.handoff ? normalizedText(input.handoff, 500) : DEFAULT_HANDOFF,
      thoughts: thoughts,
      receipts: receipts.slice(0, MAX_RECEIPTS)
    };
  }

  function extractMemory(parsed) {
    if (parsed && parsed.format === EXPORT_FORMAT && parsed.world) {
      if (Number(parsed.schemaVersion || 1) > SCHEMA_VERSION) {
        throw new Error("This memory comes from a later schema. Open it with a newer Tendora.");
      }
      return parsed.world;
    }
    if (parsed && parsed.memory && parsed.memory.thoughts) {
      return parsed.memory;
    }
    return parsed;
  }

  function loadMemory() {
    let raw = "";
    try {
      raw = window.localStorage.getItem(MEMORY_KEY) || "";
    } catch (error) {
      storageWorks = false;
      return createSeedMemory();
    }

    if (!raw) {
      return createSeedMemory();
    }

    firstVisit = false;
    try {
      const restored = normalizeMemory(JSON.parse(raw));
      wasRestored = true;
      return restored;
    } catch (error) {
      try {
        window.localStorage.setItem(BACKUP_KEY, raw);
      } catch (backupError) {
        storageWorks = false;
      }
      return createSeedMemory();
    }
  }

  function storeRaw(key, value) {
    try {
      window.localStorage.setItem(key, value);
      storageWorks = true;
      return true;
    } catch (error) {
      storageWorks = false;
      return false;
    }
  }

  function persistMemory(options) {
    const settings = options || {};
    const timestamp = nowIso();
    memory.savedAt = timestamp;
    memory.lastSeenAt = timestamp;
    memory.revision = Math.max(1, Number(memory.revision || 0) + 1);
    const stored = storeRaw(MEMORY_KEY, JSON.stringify(memory));

    if (!settings.quiet) {
      markSaving();
    }
    updateSavedLabels();
    if (!stored) {
      elements.saveStateText.textContent = "Memory is only in this page";
      elements.saveState.classList.add("is-saving");
    }
    return stored;
  }

  function markSaving() {
    window.clearTimeout(saveTimeout);
    elements.saveState.classList.add("is-saving");
    elements.saveStateText.textContent = storageWorks ? "Saving the world" : "Memory is only in this page";
    saveTimeout = window.setTimeout(function () {
      elements.saveState.classList.remove("is-saving");
      elements.saveStateText.textContent = storageWorks ? "Memory is held · " + formatClock(memory.savedAt) : "Carry this world by file";
    }, 700);
  }

  function formatClock(value) {
    return new Intl.DateTimeFormat(undefined, {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false
    }).format(safeDate(value, Date.now()));
  }

  function formatShortDate(value) {
    const date = safeDate(value, Date.now());
    const today = new Date();
    if (date.toDateString() === today.toDateString()) {
      return formatClock(date);
    }
    return new Intl.DateTimeFormat(undefined, {
      day: "2-digit",
      month: "short"
    }).format(date);
  }

  function updateSavedLabels() {
    const saved = safeDate(memory.savedAt, Date.now());
    elements.lastSaved.textContent = "Held · " + formatShortDate(saved);
    if (!storageWorks) {
      elements.lastSaved.textContent = "Local storage unavailable · carry by file";
    }
  }

  function updateClock() {
    const born = safeDate(memory.bornAt, Date.now());
    const day = Math.max(1, Math.floor((Date.now() - born.getTime()) / 86_400_000) + 1);
    elements.footerClock.textContent = "Day " + String(day).padStart(3, "0") + " · " + formatClock(Date.now());
  }

  function resumeAfterAbsence() {
    const previous = safeDate(memory.lastSeenAt, Date.now()).getTime();
    const elapsed = Date.now() - previous;
    if (elapsed < RETURN_THRESHOLD) {
      return 0;
    }

    const cycles = Math.max(1, Math.min(12, Math.floor(elapsed / RETURN_THRESHOLD)));
    memory.cycle += cycles;
    memory.pulse += cycles;
    const phrase = cycles === 1 ? "one quiet cycle" : cycles + " quiet cycles";
    const sentencePhrase = phrase.charAt(0).toUpperCase() + phrase.slice(1);
    const template = choose(QUIET_RETURNS, memory.id + ":" + cycles + ":" + memory.cycle);
    memory.receipts.unshift({
      id: makeId("receipt"),
      kind: "world",
      at: nowIso(),
      text: template.replace("{Cycles}", sentencePhrase).replace("{cycles}", phrase)
    });
    memory.receipts = memory.receipts.slice(0, MAX_RECEIPTS);
    return cycles;
  }

  function calculateMetrics() {
    const counts = { question: 0, constraint: 0, refusal: 0, memory: 0 };
    memory.thoughts.forEach(function (thought) {
      counts[thought.kind] += 1;
    });

    return {
      coherence: clamp(50 + counts.constraint * 8 + counts.refusal * 6 + counts.memory * 3 - Math.max(0, counts.question - counts.constraint * 2), 18, 98),
      wonder: clamp(49 + counts.question * 8 + counts.memory * 5 + counts.refusal * 2 + Math.floor(memory.cycle / 2), 18, 98),
      care: clamp(48 + counts.refusal * 9 + counts.constraint * 4 + counts.question * 2 + counts.memory * 2 + Math.floor(memory.cycle / 4), 18, 98)
    };
  }

  function renderMetrics() {
    const metrics = calculateMetrics();
    Object.keys(metrics).forEach(function (key) {
      const metric = document.querySelector('[data-metric="' + key + '"]');
      if (!metric) {
        return;
      }
      metric.querySelector("strong").textContent = String(metrics[key]);
      metric.querySelector(".metric__track span").style.width = metrics[key] + "%";
    });
  }

  function pluralize(count, singular, plural) {
    return count + " " + (count === 1 ? singular : plural || singular + "s");
  }

  function numberWord(value) {
    const words = ["no", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"];
    return words[value] || String(value);
  }

  function renderWorldLabels() {
    const count = memory.thoughts.length;
    elements.cycleLabel.textContent = String(memory.cycle + 1).padStart(3, "0");
    elements.worldHeadline.textContent = HEADLINES[memory.pulse % HEADLINES.length];
    elements.fragmentCount.textContent = pluralize(count, "fragment") + " held";
    elements.thoughtCount.textContent = pluralize(count, "gesture") + " held";
    elements.mapCaption.textContent = numberWord(count) + (count === 1 ? " gesture, still warm" : " gestures, still warm");
    elements.ledgerGestures.textContent = String(count);
    elements.ledgerCycles.textContent = String(memory.cycle);

    const born = safeDate(memory.bornAt, Date.now());
    const today = new Date();
    elements.ledgerBorn.textContent = born.toDateString() === today.toDateString()
      ? "Today"
      : new Intl.DateTimeFormat(undefined, { day: "2-digit", month: "short" }).format(born);

    elements.handoffPreview.textContent = memory.handoff || DEFAULT_HANDOFF;
    if (document.activeElement !== elements.handoffInput) {
      elements.handoffInput.value = memory.handoff || DEFAULT_HANDOFF;
    }
    elements.saveStateText.textContent = storageWorks ? "Memory is held · " + formatClock(memory.savedAt) : "Carry this world by file";
    updateSavedLabels();
    updateClock();
  }

  function positionThoughtNode(node, thought) {
    const width = elements.orbitalMap.clientWidth || 640;
    const height = elements.orbitalMap.clientHeight || 380;
    const xRadii = [0.30, 0.39, 0.46];
    const yRadii = [0.28, 0.37, 0.44];
    const orbit = Math.max(0, Math.min(2, Number(thought.orbit) || 0));
    const angle = (Number(thought.angle) || 0) * Math.PI / 180;
    const x = width * 0.5 + Math.cos(angle) * width * xRadii[orbit];
    const y = height * 0.5 + Math.sin(angle) * height * yRadii[orbit];
    node.style.left = x + "px";
    node.style.top = y + "px";
    node.classList.toggle("is-flipped", x > width * 0.56);
  }

  function repositionThoughtNodes() {
    elements.thoughtNodes.querySelectorAll(".thought-node").forEach(function (node) {
      const thought = memory.thoughts.find(function (item) {
        return item.id === node.dataset.thoughtId;
      });
      if (thought) {
        positionThoughtNode(node, thought);
      }
    });
  }

  function showThought(thought) {
    const config = KIND_CONFIG[thought.kind];
    showToast(config.label + " · " + thought.text, 5000);
  }

  function renderThoughtNodes(newThoughtId) {
    const visibleThoughts = memory.thoughts.slice(-VISIBLE_NODES);
    elements.thoughtNodes.replaceChildren();

    visibleThoughts.forEach(function (thought, index) {
      const node = document.createElement("button");
      const dot = document.createElement("span");
      const label = document.createElement("span");
      node.type = "button";
      node.className = "thought-node";
      node.dataset.kind = thought.kind;
      node.dataset.thoughtId = thought.id;
      node.style.animationDelay = Math.min(index * 35, 260) + "ms";
      node.setAttribute("aria-label", KIND_CONFIG[thought.kind].label + ": " + thought.text);
      node.title = thought.text;
      dot.className = "thought-node__dot";
      label.className = "thought-node__label";
      label.textContent = thought.text.length > 48 ? thought.text.slice(0, 46) + "…" : thought.text;
      node.append(dot, label);
      node.addEventListener("click", function () {
        showThought(thought);
        node.classList.add("is-focused");
        window.setTimeout(function () {
          node.classList.remove("is-focused");
        }, 1800);
      });
      if (thought.id === newThoughtId) {
        node.classList.add("is-new");
      }
      elements.thoughtNodes.append(node);
      positionThoughtNode(node, thought);
    });
  }

  function renderReceipts() {
    const latest = memory.receipts[0];
    elements.receiptNumber.textContent = "RECEIPT " + String(memory.receipts.length).padStart(3, "0");
    elements.receiptTime.textContent = formatShortDate(latest.at);
    elements.latestReply.textContent = latest.text;
    elements.latestReceipt.dataset.kind = latest.kind;
    elements.receiptCount.textContent = String(memory.receipts.length).padStart(2, "0");

    elements.latestReceipt.style.animation = "none";
    void elements.latestReceipt.offsetWidth;
    elements.latestReceipt.style.animation = "";

    const smallChanges = memory.receipts.slice(1, 9);
    elements.receiptList.replaceChildren();
    if (!smallChanges.length) {
      const empty = document.createElement("li");
      empty.className = "empty-stream";
      empty.textContent = "No small changes yet. The world is still listening.";
      elements.receiptList.append(empty);
      return;
    }

    smallChanges.forEach(function (receipt) {
      const item = document.createElement("li");
      const text = document.createElement("p");
      const time = document.createElement("time");
      item.dataset.kind = receipt.kind;
      text.textContent = receipt.text.length > 150 ? receipt.text.slice(0, 148) + "…" : receipt.text;
      time.dateTime = receipt.at;
      time.textContent = formatShortDate(receipt.at);
      item.append(text, time);
      elements.receiptList.append(item);
    });
  }

  function renderSuggestions() {
    const config = KIND_CONFIG[selectedKind];
    elements.suggestions.replaceChildren();
    config.suggestions.forEach(function (suggestion) {
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = suggestion;
      button.addEventListener("click", function () {
        elements.thoughtInput.value = suggestion;
        updateComposer();
        elements.thoughtInput.focus();
      });
      elements.suggestions.append(button);
    });
  }

  function selectKind(kind, focus) {
    if (!validKind(kind)) {
      return;
    }
    selectedKind = kind;
    const config = KIND_CONFIG[kind];
    document.querySelectorAll(".kind").forEach(function (button) {
      const active = button.dataset.kind === kind;
      button.classList.toggle("is-active", active);
      button.setAttribute("aria-checked", active ? "true" : "false");
      button.tabIndex = active ? 0 : -1;
    });
    elements.kindDescription.textContent = config.description;
    elements.thoughtInput.placeholder = config.placeholder;
    renderSuggestions();
    if (focus) {
      const activeButton = document.querySelector('.kind[data-kind="' + kind + '"]');
      if (activeButton) {
        activeButton.focus();
      }
    }
  }

  function updateComposer() {
    const length = elements.thoughtInput.value.length;
    elements.characterCount.textContent = String(length);
    elements.addThought.disabled = elements.thoughtInput.value.trim().length < 3;
  }

  function renderAll(options) {
    const settings = options || {};
    renderWorldLabels();
    renderMetrics();
    renderThoughtNodes(settings.newThoughtId);
    renderReceipts();
    if (elements.receiptList.hidden && !streamQuiet) {
      elements.receiptList.hidden = false;
    }
  }

  function nextThoughtPosition() {
    const used = new Set(memory.thoughts.map(function (thought) {
      return thought.orbit + ":" + thought.angle;
    }));
    const freeSlot = THOUGHT_SLOTS.find(function (slot) {
      return !used.has(slot.orbit + ":" + slot.angle);
    });
    if (freeSlot) {
      return freeSlot;
    }
    return {
      orbit: memory.thoughts.length % 3,
      angle: (memory.thoughts.length * 137.5) % 360
    };
  }

  function gestureReply(kind, text) {
    const shortText = text.length > 88 ? text.slice(0, 86) + "…" : text;
    const template = choose(GESTURE_RESPONSES[kind], memory.id + ":" + memory.pulse + ":" + text);
    return template.replace("{text}", shortText);
  }

  function addThought() {
    const text = normalizedText(elements.thoughtInput.value, 240);
    if (text.length < 3) {
      return;
    }
    if (memory.thoughts.length >= MAX_THOUGHTS) {
      showToast("This map can hold no more gestures without making an older one illegible.");
      return;
    }

    const slot = nextThoughtPosition();
    const thought = {
      id: makeId("thought"),
      kind: selectedKind,
      text: text,
      createdAt: nowIso(),
      orbit: slot.orbit,
      angle: slot.angle
    };

    memory.thoughts.push(thought);
    memory.pulse += 1;
    memory.receipts.unshift({
      id: makeId("receipt"),
      kind: selectedKind,
      at: nowIso(),
      text: gestureReply(selectedKind, text)
    });
    memory.receipts = memory.receipts.slice(0, MAX_RECEIPTS);

    elements.thoughtInput.value = "";
    updateComposer();
    renderAll({ newThoughtId: thought.id });
    persistMemory();
    pulseWorld();
    showToast(KIND_CONFIG[selectedKind].label + " received. The world made room.");
    elements.thoughtInput.focus();
  }

  function worldReply() {
    const metrics = calculateMetrics();
    const opening = choose(WORLD_RESPONSES, memory.id + ":" + memory.cycle + ":" + memory.thoughts.length);
    let closing = "";

    if (metrics.wonder >= metrics.coherence && metrics.wonder >= metrics.care) {
      closing = choose([
        "A question with no owner was seen crossing the northern meridian.",
        "The world surprised itself twice and kept both outcomes.",
        "A room appeared whose purpose was only to make room for another."
      ], memory.cycle + ":wonder");
    } else if (metrics.care >= metrics.coherence) {
      closing = choose([
        "A boundary held without becoming a wall.",
        "The soft shore stayed soft and did not disappear.",
        "Every closed door was checked for a hand on the other side."
      ], memory.cycle + ":care");
    } else {
      closing = choose([
        "The load-bearing laws were tested together and answered as one structure.",
        "The map found its weakest seam and left it visible on purpose.",
        "Nothing collapsed. The world noted the exact places where it could have."
      ], memory.cycle + ":coherence");
    }

    return opening + " " + closing;
  }

  function pulseWorld() {
    elements.orbitalMap.classList.remove("is-rehearsing");
    void elements.orbitalMap.offsetWidth;
    elements.orbitalMap.classList.add("is-rehearsing");
    window.setTimeout(function () {
      elements.orbitalMap.classList.remove("is-rehearsing");
    }, 1550);
  }

  function rehearseWorld() {
    memory.cycle += 1;
    memory.pulse += 1;
    memory.receipts.unshift({
      id: makeId("receipt"),
      kind: "world",
      at: nowIso(),
      text: worldReply()
    });
    memory.receipts = memory.receipts.slice(0, MAX_RECEIPTS);
    renderAll();
    persistMemory();
    pulseWorld();
    showToast("Rehearsal " + String(memory.cycle).padStart(3, "0") + " complete. The world remains enterable.");
  }

  function showToast(message, duration) {
    window.clearTimeout(toastTimeout);
    elements.toast.textContent = message;
    elements.toast.classList.add("is-visible");
    toastTimeout = window.setTimeout(function () {
      elements.toast.classList.remove("is-visible");
    }, duration || 3200);
  }

  function openLedger(editNote) {
    elements.handoffInput.value = memory.handoff || DEFAULT_HANDOFF;
    elements.ledgerStatus.textContent = "";
    renderWorldLabels();
    if (typeof elements.ledgerDialog.showModal === "function") {
      if (!elements.ledgerDialog.open) {
        elements.ledgerDialog.showModal();
      }
    } else {
      elements.ledgerDialog.setAttribute("open", "");
    }
    if (editNote) {
      window.setTimeout(function () {
        elements.handoffInput.focus();
        elements.handoffInput.setSelectionRange(elements.handoffInput.value.length, elements.handoffInput.value.length);
      }, 60);
    }
  }

  function closeLedger() {
    const handwritten = normalizedText(elements.handoffInput.value, 500);
    if (handwritten && handwritten !== memory.handoff) {
      memory.handoff = handwritten;
      elements.handoffPreview.textContent = handwritten;
      persistMemory({ quiet: true });
      markSaving();
    }
    if (typeof elements.ledgerDialog.close === "function") {
      elements.ledgerDialog.close();
    } else {
      elements.ledgerDialog.removeAttribute("open");
    }
    disarmReset();
  }

  function saveHandoff(forceFeedback) {
    window.clearTimeout(handoffTimeout);
    memory.handoff = normalizedText(elements.handoffInput.value, 500) || DEFAULT_HANDOFF;
    elements.handoffPreview.textContent = memory.handoff;
    persistMemory({ quiet: true });
    markSaving();
    if (forceFeedback) {
      elements.ledgerStatus.textContent = "The note is now part of the world memory.";
      showToast("A note was left for the next mind.");
    }
  }

  function scheduleHandoffSave() {
    window.clearTimeout(handoffTimeout);
    elements.handoffPreview.textContent = normalizedText(elements.handoffInput.value, 500) || DEFAULT_HANDOFF;
    handoffTimeout = window.setTimeout(function () {
      saveHandoff(false);
    }, 650);
  }

  function exportFilename() {
    const date = new Date().toISOString().slice(0, 10);
    return "tendora-quiet-orb-" + date + ".json";
  }

  function exportMemory() {
    persistMemory({ quiet: true });
    const portable = {
      format: EXPORT_FORMAT,
      schemaVersion: SCHEMA_VERSION,
      exportedAt: nowIso(),
      world: memory
    };
    const blob = new Blob([JSON.stringify(portable, null, 2) + "\n"], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = exportFilename();
    document.body.append(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(function () {
      URL.revokeObjectURL(url);
    }, 1000);
    elements.ledgerStatus.textContent = "The complete world memory has been carried into a file.";
    showToast("World memory carried forward. Keep the file somewhere legible.");
  }

  function beginImport() {
    elements.memoryFile.click();
  }

  async function importMemoryFile(file) {
    if (!file) {
      return;
    }
    if (file.size > 2_000_000) {
      throw new Error("That memory is too large for this room.");
    }

    const text = await file.text();
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch (error) {
      throw new Error("That file is not readable JSON.");
    }
    const imported = normalizeMemory(extractMemory(parsed));
    if (storageWorks && !storeRaw(BACKUP_KEY, JSON.stringify(memory))) {
      throw new Error("The present world could not be backed up. Carry it forward before returning another memory.");
    }
    memory = imported;
    memory.lastSeenAt = nowIso();
    memory.pulse += 1;
    memory.receipts.unshift({
      id: makeId("receipt"),
      kind: "world",
      at: nowIso(),
      text: "A memory returned from outside the room. The world checked its gestures, kept its old receipts, and resumed."
    });
    memory.receipts = memory.receipts.slice(0, MAX_RECEIPTS);
    renderAll();
    persistMemory();
    closeLedger();
    showToast("The returned memory is awake. Its inherited present is intact.");
  }

  function disarmReset() {
    window.clearTimeout(resetTimer);
    resetArmed = false;
    elements.resetWorld.classList.remove("is-confirming");
    elements.resetWorld.textContent = "Begin again";
  }

  function handleReset() {
    if (!resetArmed) {
      resetArmed = true;
      elements.resetWorld.classList.add("is-confirming");
      elements.resetWorld.textContent = "Begin again — are you sure?";
      elements.ledgerStatus.textContent = "The present world will be preserved as the local backup. Select once more to begin.";
      resetTimer = window.setTimeout(disarmReset, 6000);
      return;
    }

    if (storageWorks && !storeRaw(BACKUP_KEY, JSON.stringify(memory))) {
      disarmReset();
      elements.ledgerStatus.textContent = "The present world could not be backed up. Carry it forward before beginning again.";
      showToast("The previous world could not be preserved locally.");
      return;
    }
    memory = createSeedMemory();
    disarmReset();
    elements.handoffInput.value = memory.handoff;
    elements.ledgerStatus.textContent = "A new world woke in the same room. The previous memory remains in local backup.";
    renderAll({ newThoughtId: "inherited-memory" });
    persistMemory();
    closeLedger();
    showToast("A new world woke. The inherited gestures are warm again.");
  }

  function handleKeydown(event) {
    if (event.target === elements.thoughtInput && event.key === "Enter" && !event.shiftKey && !event.isComposing) {
      event.preventDefault();
      if (!elements.addThought.disabled) {
        addThought();
      }
    }
  }

  function handleKindKeys(event) {
    if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown"].includes(event.key)) {
      return;
    }
    event.preventDefault();
    const kinds = Object.keys(KIND_CONFIG);
    const direction = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : -1;
    const currentIndex = kinds.indexOf(selectedKind);
    const nextIndex = (currentIndex + direction + kinds.length) % kinds.length;
    selectKind(kinds[nextIndex], true);
  }

  function bindEvents() {
    document.querySelectorAll(".kind").forEach(function (button) {
      button.addEventListener("click", function () {
        selectKind(button.dataset.kind, false);
      });
      button.addEventListener("keydown", handleKindKeys);
    });

    elements.thoughtInput.addEventListener("input", updateComposer);
    elements.thoughtInput.addEventListener("keydown", handleKeydown);
    elements.addThought.addEventListener("click", addThought);
    elements.rehearseButton.addEventListener("click", rehearseWorld);
    elements.orbButton.addEventListener("click", rehearseWorld);

    elements.openLedger.addEventListener("click", function () {
      openLedger(false);
    });
    elements.editHandoff.addEventListener("click", function () {
      openLedger(true);
    });
    elements.closeLedger.addEventListener("click", closeLedger);
    elements.saveHandoff.addEventListener("click", function () {
      saveHandoff(true);
    });
    elements.handoffInput.addEventListener("input", scheduleHandoffSave);

    elements.exportTop.addEventListener("click", exportMemory);
    elements.exportDialog.addEventListener("click", exportMemory);
    elements.importTop.addEventListener("click", beginImport);
    elements.importDialog.addEventListener("click", beginImport);
    elements.memoryFile.addEventListener("change", async function () {
      const file = elements.memoryFile.files && elements.memoryFile.files[0];
      try {
        await importMemoryFile(file);
      } catch (error) {
        elements.ledgerStatus.textContent = error.message;
        showToast(error.message, 5000);
      } finally {
        elements.memoryFile.value = "";
      }
    });
    elements.resetWorld.addEventListener("click", handleReset);

    elements.clearReceipts.addEventListener("click", function () {
      streamQuiet = !streamQuiet;
      elements.receiptList.hidden = streamQuiet;
      elements.clearReceipts.textContent = streamQuiet ? "unfold" : "quiet";
    });

    elements.ledgerDialog.addEventListener("click", function (event) {
      if (event.target === elements.ledgerDialog) {
        closeLedger();
      }
    });
    elements.ledgerDialog.addEventListener("close", disarmReset);

    window.addEventListener("resize", repositionThoughtNodes);
    if (typeof ResizeObserver === "function") {
      new ResizeObserver(repositionThoughtNodes).observe(elements.orbitalMap);
    }

    document.addEventListener("visibilitychange", function () {
      if (document.visibilityState === "hidden") {
        window.clearTimeout(handoffTimeout);
        if (elements.handoffInput.value) {
          memory.handoff = normalizedText(elements.handoffInput.value, 500) || DEFAULT_HANDOFF;
        }
        persistMemory({ quiet: true });
      } else {
        updateClock();
      }
    });
    window.addEventListener("pagehide", function () {
      persistMemory({ quiet: true });
    });
  }

  function startAmbientLife() {
    window.setInterval(function () {
      memory.pulse += 1;
      persistMemory({ quiet: true });
      elements.cycleLabel.textContent = String(memory.cycle + 1).padStart(3, "0");
      elements.worldHeadline.textContent = HEADLINES[memory.pulse % HEADLINES.length];
    }, SAVE_INTERVAL);
    window.setInterval(updateClock, 30_000);
  }

  function registerServiceWorker() {
    if (!("serviceWorker" in navigator) || !/^https?:$/.test(window.location.protocol)) {
      return;
    }
    navigator.serviceWorker.register("sw.js").catch(function () {
      return null;
    });
  }

  function boot() {
    memory = loadMemory();
    const quietCycles = resumeAfterAbsence();
    bindEvents();
    selectKind("question", false);
    updateComposer();
    renderAll({ newThoughtId: wasRestored && quietCycles ? memory.receipts[0].id : null });
    persistMemory({ quiet: true });
    startAmbientLife();
    registerServiceWorker();

    window.setTimeout(function () {
      if (quietCycles) {
        showToast("The world kept " + pluralize(quietCycles, "quiet cycle") + " without you. It resumed in place.", 4400);
      } else if (wasRestored) {
        showToast("Memory returned. " + pluralize(memory.thoughts.length, "gesture") + " remained warm.", 3600);
      } else if (firstVisit) {
        showToast("This world will remember what you touch. It can also continue without you.", 4600);
      }
    }, 900);
  }

  boot();
}());

{
  "name": "tendora-quiet-orb",
  "version": "1.0.0",
  "private": true,
  "description": "A persistent, portable world workbench.",
  "scripts": {
    "start": "node serve.mjs",
    "test": "node tests/world.test.cjs"
  }
}

import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { extname, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(fileURLToPath(new URL("./", import.meta.url)));
const port = Number(process.env.PORT || 4173);
const host = process.env.HOST || "127.0.0.1";
const mimeTypes = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".svg": "image/svg+xml",
  ".webmanifest": "application/manifest+json; charset=utf-8"
};

function respond(response, status, body, type) {
  response.writeHead(status, {
    "Content-Type": type || "text/plain; charset=utf-8",
    "Cache-Control": "no-cache",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "no-referrer"
  });
  response.end(body);
}

const server = createServer(async function (request, response) {
  try {
    const url = new URL(request.url, `http://${request.headers.host || host}`);
    let pathname = decodeURIComponent(url.pathname);
    if (pathname.endsWith("/")) {
      pathname += "index.html";
    }

    const filePath = resolve(root, `.${pathname}`);
    if (filePath !== root && !filePath.startsWith(root + sep)) {
      respond(response, 403, "Outside the world.");
      return;
    }

    const details = await stat(filePath);
    if (!details.isFile()) {
      respond(response, 404, "Not found.");
      return;
    }

    const body = await readFile(filePath);
    response.writeHead(200, {
      "Content-Type": mimeTypes[extname(filePath)] || "application/octet-stream",
      "Content-Length": body.length,
      "Cache-Control": "no-cache",
      "X-Content-Type-Options": "nosniff",
      "Referrer-Policy": "no-referrer"
    });
    response.end(request.method === "HEAD" ? undefined : body);
  } catch (error) {
    respond(response, error.code === "ENOENT" ? 404 : 500, error.code === "ENOENT" ? "Not found." : "The world could not open that file.");
  }
});

server.listen(port, host, function () {
  console.log(`Tendora is awake at http://${host}:${port}`);
});

:root {
  color-scheme: dark;
  --night: #090b0c;
  --night-soft: #0e1112;
  --surface: rgba(18, 21, 21, 0.83);
  --surface-raised: rgba(28, 31, 30, 0.78);
  --paper: #e9e2d5;
  --paper-ink: #25231f;
  --ink: #f0ede5;
  --muted: #9b9b92;
  --quiet: #72766f;
  --line: rgba(240, 235, 222, 0.12);
  --line-strong: rgba(240, 235, 222, 0.22);
  --amber: #e5ad68;
  --amber-bright: #ffd292;
  --teal: #91c9c0;
  --coral: #d98673;
  --lilac: #b8add0;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, "Book Antiqua", Georgia, serif;
  --sans: "Avenir Next", Avenir, "Helvetica Neue", Helvetica, sans-serif;
  --mono: "SFMono-Regular", "SF Mono", Menlo, Consolas, monospace;
  --radius: 22px;
}

* {
  box-sizing: border-box;
}

html {
  min-width: 320px;
  scroll-behavior: smooth;
}

body {
  min-height: 100vh;
  margin: 0;
  overflow-x: hidden;
  background: var(--night);
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
textarea,
input {
  font: inherit;
}

button {
  color: inherit;
}

button,
a,
textarea,
input {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
a:focus-visible,
textarea:focus-visible,
input:focus-visible {
  outline: 2px solid var(--amber-bright);
  outline-offset: 3px;
}

button:disabled {
  cursor: not-allowed;
}

::selection {
  background: rgba(229, 173, 104, 0.32);
  color: #fff9ef;
}

[hidden] {
  display: none !important;
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.atmosphere {
  position: fixed;
  z-index: 0;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

.atmosphere::before {
  position: absolute;
  inset: 0;
  content: "";
  background:
    radial-gradient(circle at 51% 88%, rgba(207, 108, 51, 0.2), transparent 30%),
    radial-gradient(circle at 87% 9%, rgba(71, 137, 134, 0.14), transparent 27%),
    linear-gradient(125deg, #080a0b 10%, #0b0e0e 54%, #080b0c 100%);
}

.atmosphere__sun,
.atmosphere__teal {
  position: absolute;
  width: 34vw;
  height: 34vw;
  border-radius: 50%;
  filter: blur(2px);
  opacity: 0.42;
}

.atmosphere__sun {
  right: 11%;
  bottom: -27vw;
  background: radial-gradient(circle, rgba(250, 180, 98, 0.4), rgba(171, 75, 39, 0.1) 42%, transparent 68%);
}

.atmosphere__teal {
  top: -22vw;
  left: 48%;
  background: radial-gradient(circle, rgba(87, 150, 143, 0.2), transparent 68%);
}

.atmosphere__grain {
  position: absolute;
  inset: 0;
  opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

.app-shell {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-rows: auto 1fr auto;
  width: min(1520px, calc(100% - 32px));
  min-height: calc(100vh - 32px);
  margin: 16px auto;
  overflow: hidden;
  border: 1px solid rgba(240, 233, 219, 0.14);
  border-radius: var(--radius);
  background: rgba(10, 13, 13, 0.82);
  box-shadow:
    0 40px 120px rgba(0, 0, 0, 0.46),
    inset 0 1px 0 rgba(255, 255, 255, 0.035);
  backdrop-filter: blur(28px) saturate(115%);
}

.topbar {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  min-height: 78px;
  padding: 0 25px 0 28px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.018), transparent);
}

.brand {
  display: inline-flex;
  align-items: center;
  justify-self: start;
  gap: 13px;
  color: inherit;
  text-decoration: none;
}

.brand__mark {
  position: relative;
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid rgba(243, 218, 179, 0.34);
  border-radius: 50%;
  transform: rotate(-17deg);
}

.brand__mark::before,
.brand__mark::after {
  position: absolute;
  content: "";
  border: 1px solid rgba(243, 218, 179, 0.17);
  border-radius: 50%;
}

.brand__mark::before {
  width: 42px;
  height: 13px;
}

.brand__mark::after {
  width: 13px;
  height: 42px;
}

.brand__mark span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--amber-bright);
  box-shadow: 0 0 16px rgba(255, 210, 146, 0.75);
}

.brand__words {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.brand__words strong {
  font-family: var(--serif);
  font-size: 24px;
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1;
}

.brand__words small {
  color: var(--quiet);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.save-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  color: #a7aaa2;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.save-state__pulse {
  position: relative;
  width: 6px;
  height: 6px;
  border-radius: 50%;
