  min-height: 0;
}

.eyebrow {
  color: #858981;
  font-family: var(--mono);
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.17em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow__rule {
  display: inline-block;
  width: 22px;
  height: 1px;
  margin: 0 8px 2px;
  background: var(--line-strong);
}

.eyebrow b {
