}

.rail-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.provenance {
  color: #6f736c;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.memory-rail h1 {
  margin: 25px 0 13px;
  font-family: var(--serif);
  font-size: clamp(42px, 3.5vw, 57px);
  font-weight: 400;
  letter-spacing: -0.052em;
  line-height: 0.85;
}

.memory-rail h1 em {
  color: var(--amber-bright);
  font-weight: 400;
}

.world-intro {
  max-width: 235px;
  margin: 0;
  color: #9e9f96;
  font-family: var(--serif);
  font-size: 15px;
  line-height: 1.5;
}

.world-metrics {
  display: grid;
  gap: 17px;
  margin-top: 33px;
}

.metric__heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 7px;
}

.metric__heading span {
  color: #999b93;
  font-size: 10px;
  letter-spacing: 0.05em;
}

.metric__heading strong {
  color: #dad5ca;
  font-family: var(--mono);
  font-size: 11px;
  font-weight: 400;
}

.metric__track {
  position: relative;
  height: 1px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.09);
}

.metric__track::after {
  position: absolute;
  top: -1px;
  right: 0;
  width: 1px;
  height: 3px;
  content: "";
  background: rgba(255, 255, 255, 0.18);
}

.metric__track span {
  display: block;
  width: 67%;
  height: 100%;
  background: linear-gradient(90deg, rgba(229, 173, 104, 0.3), var(--amber));
