  transition: width 800ms cubic-bezier(0.22, 1, 0.36, 1), background 500ms ease;
}

.metric[data-metric="wonder"] .metric__track span {
  background: linear-gradient(90deg, rgba(145, 201, 192, 0.24), var(--teal));
  box-shadow: 0 0 7px rgba(145, 201, 192, 0.4);
}

.metric[data-metric="care"] .metric__track span {
  background: linear-gradient(90deg, rgba(217, 134, 115, 0.24), var(--coral));
  box-shadow: 0 0 7px rgba(217, 134, 115, 0.4);
}

.inherited-memory {
  position: relative;
  margin: 33px 0 0;
  padding: 19px 0 18px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.inherited-memory::before {
  position: absolute;
  top: -3px;
  left: 0;
  width: 5px;
  height: 5px;
  content: "";
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 10px rgba(229, 173, 104, 0.6);
}

.inherited-memory blockquote {
  margin: 0;
  color: #c8c2b7;
  font-family: var(--serif);
  font-size: 14px;
  font-style: italic;
  line-height: 1.55;
}

.inherited-memory figcaption {
  display: flex;
  gap: 6px;
  margin-top: 11px;
  color: #71756e;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.inherited-memory figcaption span {
  color: #4f524d;
}

.continuity-card {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 12px;
  margin-top: auto;
  padding: 20px 0 0;
}

.continuity-card__orbit {
  position: relative;
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid rgba(145, 201, 192, 0.22);
  border-radius: 50%;
}

.continuity-card__orbit::before {
  position: absolute;
  width: 39px;
  height: 12px;
  content: "";
  border: 1px solid rgba(145, 201, 192, 0.17);
  border-radius: 50%;
  transform: rotate(-33deg);
}

.continuity-card__orbit span {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 8px rgba(145, 201, 192, 0.7);
}

.continuity-card p {
  margin: 4px 0 2px;
  color: #c2beb4;
  font-family: var(--serif);
  font-size: 13px;
}

.continuity-card small {
  color: #696d67;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.04em;
}

.icon-button {
  display: grid;
  width: 31px;
  height: 31px;
  padding: 0;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: transparent;
  color: #969990;
  cursor: pointer;
  transition: color 180ms ease, border-color 180ms ease, background 180ms ease;
}

.icon-button:hover {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.04);
  color: var(--ink);
}

.icon-button svg {
  width: 14px;
  height: 14px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.3;
}

.world-stage {
  display: flex;
  min-width: 0;
  flex-direction: column;
  padding: 25px 28px 17px;
  background:
    radial-gradient(circle at 50% 42%, rgba(176, 112, 57, 0.055), transparent 34%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.012), transparent 25%);
}

.stage-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  min-height: 58px;
  gap: 18px;
}

.stage-heading h2 {
  margin: 8px 0 0;
  color: #ded8cd;
  font-family: var(--serif);
  font-size: clamp(22px, 2vw, 30px);
  font-weight: 400;
  letter-spacing: -0.025em;
  line-height: 1.12;
}

.stage-options {
  display: flex;
  align-items: center;
  gap: 11px;
  color: #73776f;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.stage-seal {
  position: relative;
  display: grid;
  width: 54px;
  height: 54px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid rgba(229, 173, 104, 0.18);
  border-radius: 50%;
  color: #8d8678;
}

.stage-seal::before,
.stage-seal::after {
  position: absolute;
  content: "";
  border-radius: 50%;
}

.stage-seal::before {
  inset: 5px;
  border: 1px dashed rgba(229, 173, 104, 0.19);
  animation: slow-spin 25s linear infinite;
}

.stage-seal::after {
  top: 2px;
  width: 4px;
  height: 4px;
  background: var(--amber);
  box-shadow: 0 0 8px rgba(229, 173, 104, 0.7);
}

.stage-seal span {
  width: 6px;
  height: 6px;
  border: 1px solid var(--amber);
  border-radius: 50%;
}

.stage-seal small {
  position: absolute;
  top: 61px;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.orbital-map {
  position: relative;
  min-height: 315px;
  flex: 1 1 390px;
  margin: 3px -3px 0;
  overflow: hidden;
  isolation: isolate;
}

.orbital-map::before,
.orbital-map::after {
  position: absolute;
  z-index: -1;
  content: "";
  pointer-events: none;
}

.orbital-map::before {
  top: 50%;
  left: 50%;
  width: min(70%, 430px);
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(214, 123, 54, 0.13), rgba(132, 67, 33, 0.04) 43%, transparent 70%);
  transform: translate(-50%, -50%);
  filter: blur(20px);
}

.orbital-map::after {
  inset: 0;
  background: linear-gradient(90deg, rgba(10, 13, 13, 0.74), transparent 16%, transparent 84%, rgba(10, 13, 13, 0.66));
}

.map-stars {
  position: absolute;
  inset: 0;
  z-index: -2;
  opacity: 0.68;
  background-image:
    radial-gradient(circle at 8% 27%, rgba(255, 236, 204, 0.72) 0 0.7px, transparent 1px),
    radial-gradient(circle at 17% 68%, rgba(255, 236, 204, 0.5) 0 0.6px, transparent 1px),
    radial-gradient(circle at 29% 17%, rgba(255, 236, 204, 0.58) 0 0.7px, transparent 1px),
    radial-gradient(circle at 37% 72%, rgba(255, 236, 204, 0.45) 0 0.6px, transparent 1px),
    radial-gradient(circle at 46% 14%, rgba(172, 222, 212, 0.56) 0 0.7px, transparent 1px),
    radial-gradient(circle at 55% 79%, rgba(255, 236, 204, 0.52) 0 0.6px, transparent 1px),
    radial-gradient(circle at 63% 24%, rgba(255, 236, 204, 0.62) 0 0.7px, transparent 1px),
    radial-gradient(circle at 73% 61%, rgba(172, 222, 212, 0.4) 0 0.6px, transparent 1px),
    radial-gradient(circle at 84% 18%, rgba(255, 236, 204, 0.48) 0 0.7px, transparent 1px),
    radial-gradient(circle at 91% 73%, rgba(255, 236, 204, 0.5) 0 0.6px, transparent 1px),
    radial-gradient(circle at 22% 42%, rgba(255, 236, 204, 0.3) 0 0.5px, transparent 1px),
    radial-gradient(circle at 69% 85%, rgba(255, 236, 204, 0.28) 0 0.5px, transparent 1px);
}

.orbit-lines {
  position: absolute;
  z-index: -1;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.orbit-line {
  fill: none;
  stroke: rgba(234, 218, 193, 0.14);
  stroke-width: 0.7;
  vector-effect: non-scaling-stroke;
}

.orbit-line--outer {
  stroke-dasharray: 1 7;
  stroke-linecap: round;
  opacity: 0.58;
}

.orbit-line--middle {
  stroke: url(#orbitFade);
}

.orbit-line--inner {
  stroke-dasharray: 1 5;
  opacity: 0.6;
}

.orbit-arc {
  fill: none;
  stroke: rgba(229, 173, 104, 0.34);
  stroke-width: 0.9;
  vector-effect: non-scaling-stroke;
}

.orbit-arc--faint {
  stroke: rgba(145, 201, 192, 0.13);
  stroke-dasharray: 2 8;
}

.meridian {
  fill: none;
  stroke: rgba(238, 229, 210, 0.12);
  stroke-width: 0.7;
  vector-effect: non-scaling-stroke;
}

.orbit-dot {
  fill: var(--amber-bright);
  filter: drop-shadow(0 0 5px rgba(255, 210, 146, 0.8));
}

.map-coordinate {
  position: absolute;
  z-index: 3;
  color: #656a63;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.12em;
  pointer-events: none;
}

.map-coordinate--north {
  top: 3px;
  left: 50%;
  transform: translateX(-50%);
}

.map-coordinate--east {
  top: 51%;
  right: 12px;
  writing-mode: vertical-rl;
}

.map-coordinate--west {
  bottom: 29%;
  left: 13px;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

.orb {
  position: absolute;
  z-index: 3;
  top: 50%;
  left: 50%;
  width: clamp(124px, 14vw, 166px);
  aspect-ratio: 1;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  transform: translate(-50%, -50%);
  transition: transform 500ms cubic-bezier(0.22, 1, 0.36, 1);
}

.orb:hover {
  transform: translate(-50%, -50%) scale(1.025);
}

.orb__halo,
.orb__body,
.orb__rim,
.orb__caption {
  position: absolute;
  border-radius: 50%;
}

.orb__halo {
  inset: -45%;
  background: radial-gradient(circle, rgba(241, 153, 67, 0.17), rgba(186, 87, 41, 0.05) 44%, transparent 69%);
  filter: blur(5px);
  animation: orb-breathe 7s ease-in-out infinite;
}

.orb__body {
  inset: 0;
  overflow: hidden;
  border: 1px solid rgba(255, 237, 203, 0.4);
  background:
    radial-gradient(circle at 34% 27%, rgba(255, 249, 212, 0.94), transparent 9%),
    radial-gradient(circle at 41% 37%, #ffd189 0, #eca85d 20%, #d5793b 43%, #9c4728 63%, #4e2017 82%, #21100d 100%);
  box-shadow:
    0 0 24px rgba(246, 161, 78, 0.36),
    0 0 70px rgba(217, 104, 46, 0.2),
    inset -20px -24px 35px rgba(26, 10, 8, 0.52),
    inset 15px 12px 25px rgba(255, 222, 168, 0.18);
}

.orb__body::after {
  position: absolute;
  inset: 0;
  content: "";
  border-radius: 50%;
  opacity: 0.25;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 100 100' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='o'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.6' numOctaves='3'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23o)' opacity='.45'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}

.orb__cloud {
  position: absolute;
  z-index: 1;
  height: 12%;
  border-radius: 50%;
  background: rgba(255, 225, 181, 0.16);
  filter: blur(6px);
  transform: rotate(-12deg);
}

.orb__cloud--one {
  top: 32%;
  left: 19%;
  width: 57%;
}

.orb__cloud--two {
  top: 48%;
  left: 32%;
  width: 54%;
  opacity: 0.54;
  transform: rotate(8deg);
}

.orb__horizon {
  position: absolute;
  z-index: 2;
  right: -18%;
  bottom: -37%;
  left: -18%;
  height: 76%;
  border: 1px solid rgba(255, 205, 144, 0.24);
  border-radius: 50%;
  background:
    radial-gradient(ellipse at 40% 0%, rgba(255, 179, 103, 0.2), transparent 28%),
    linear-gradient(180deg, rgba(77, 30, 22, 0.1), rgba(22, 11, 10, 0.78));
  box-shadow: 0 -9px 26px rgba(255, 174, 91, 0.12);
  transform: rotate(-7deg);
}

.orb__rim {
  inset: -3px;
  border: 1px solid rgba(255, 225, 177, 0.18);
  box-shadow: inset 0 0 0 1px rgba(87, 37, 23, 0.4);
  pointer-events: none;
}

.orb__caption {
  top: calc(100% + 20px);
  left: 50%;
  width: max-content;
  color: #6d7069;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  transform: translateX(-50%);
  transition: color 200ms ease;
}

.orb:hover .orb__caption {
  color: #b7ab99;
}

.orbital-map.is-rehearsing .orb__body {
  animation: rehearse-orb 1.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.orbital-map.is-rehearsing .orbit-line {
  animation: orbit-bloom 1.5s ease-out;
}

.thought-nodes {
  position: absolute;
  z-index: 5;
  inset: 0;
  pointer-events: none;
}

.thought-node {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 7px;
  max-width: 170px;
  padding: 4px;
  border: 0;
  border-radius: 7px;
  background: transparent;
  color: #a7a69e;
  cursor: pointer;
  pointer-events: auto;
  text-align: left;
  transform: translate(-50%, -50%);
  transition: color 180ms ease, transform 180ms ease;
  animation: node-arrive 650ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.thought-node:hover,
.thought-node.is-focused {
  color: #f0e9dc;
  transform: translate(-50%, -50%) scale(1.045);
}

.thought-node__dot {
  position: relative;
  width: 7px;
  height: 7px;
  flex: 0 0 auto;
  border: 1px solid currentColor;
  border-radius: 50%;
  background: #111414;
  box-shadow: 0 0 8px currentColor;
}

.thought-node__dot::after {
  position: absolute;
  inset: -4px;
  content: "";
  border: 1px solid currentColor;
  border-radius: 50%;
  opacity: 0.18;
}

.thought-node__label {
  overflow: hidden;
  padding: 4px 6px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 4px;
  background: rgba(10, 13, 13, 0.66);
  font-family: var(--serif);
  font-size: 11px;
  line-height: 1.22;
  text-overflow: ellipsis;
  white-space: nowrap;
  backdrop-filter: blur(6px);
}

.thought-node[data-kind="question"] {
  color: var(--teal);
}

.thought-node[data-kind="constraint"] {
  color: var(--amber);
}

.thought-node[data-kind="refusal"] {
  color: var(--coral);
}

.thought-node[data-kind="memory"] {
  color: var(--lilac);
}

.thought-node.is-new .thought-node__dot {
  animation: new-thought 1s ease-out;
}

.thought-node.is-flipped {
  flex-direction: row-reverse;
  text-align: right;
}

.map-caption {
  position: absolute;
  z-index: 4;
  bottom: 4px;
  left: 50%;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #5e625c;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  transform: translateX(-50%);
}

.map-caption strong {
  color: #85857d;
  font-weight: 500;
}

.gesture-panel {
  position: relative;
  padding: 14px 17px 13px;
  border: 1px solid rgba(238, 229, 211, 0.12);
  border-radius: 14px;
  background:
    linear-gradient(125deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.012)),
    rgba(11, 14, 14, 0.5);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

.gesture-panel__heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 10px;
}

.gesture-panel__heading h3 {
  margin: 3px 0 0;
  font-family: var(--serif);
  font-size: 20px;
  font-weight: 400;
  letter-spacing: -0.02em;
}

.gesture-panel__heading p {
  max-width: 220px;
  margin: 0 0 2px;
  color: #7f827b;
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  line-height: 1.35;
  text-align: right;
}

.gesture-kinds {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  margin-bottom: 8px;
}

.kind {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.015);
  color: #8b8e86;
  cursor: pointer;
  text-align: left;
  transition: border-color 180ms ease, background 180ms ease, color 180ms ease;
}

.kind:hover {
  border-color: rgba(255, 255, 255, 0.14);
  color: #c8c5bc;
}

.kind.is-active {
  border-color: rgba(145, 201, 192, 0.32);
  background: rgba(145, 201, 192, 0.07);
  color: var(--teal);
}

.kind[data-kind="constraint"].is-active {
  border-color: rgba(229, 173, 104, 0.34);
  background: rgba(229, 173, 104, 0.07);
  color: var(--amber);
}

.kind[data-kind="refusal"].is-active {
  border-color: rgba(217, 134, 115, 0.32);
  background: rgba(217, 134, 115, 0.07);
  color: var(--coral);
}

.kind[data-kind="memory"].is-active {
  border-color: rgba(184, 173, 208, 0.32);
  background: rgba(184, 173, 208, 0.07);
  color: var(--lilac);
}

.kind__glyph {
  display: grid;
  width: 23px;
  height: 23px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-family: var(--serif);
  font-size: 13px;
  line-height: 1;
  opacity: 0.8;
}

.kind > span:last-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.kind strong {
  overflow: hidden;
  color: #c9c5ba;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.kind.is-active strong {
  color: inherit;
}

.kind small {
  color: #666a64;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.gesture-input {
  position: relative;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  background: rgba(4, 6, 6, 0.38);
  transition: border-color 180ms ease, background 180ms ease;
}

.gesture-input:focus-within {
  border-color: rgba(145, 201, 192, 0.35);
  background: rgba(4, 6, 6, 0.52);
}

.gesture-input textarea {
  display: block;
  width: 100%;
  min-height: 48px;
  max-height: 105px;
  padding: 12px 13px 5px;
  resize: none;
  border: 0;
  outline: 0;
  overflow-y: auto;
  background: transparent;
  color: #e5dfd4;
  font-family: var(--serif);
  font-size: 14px;
  line-height: 1.4;
}

.gesture-input textarea::placeholder {
  color: #61655f;
  font-style: italic;
}

.gesture-input__actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 11px;
  padding: 0 7px 7px 13px;
}

.character-count,
.enter-hint {
  color: #575b55;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.character-count b {
  color: #797c75;
  font-weight: 400;
}

.enter-hint {
  margin-left: auto;
}

.button--send {
  min-height: 28px;
  padding: 0 10px;
  border-color: rgba(229, 173, 104, 0.3);
  background: var(--paper);
  color: var(--paper-ink);
  font-size: 8px;
}

.button--send svg {
  width: 13px;
  height: 13px;
}

.button--send:hover:not(:disabled) {
  background: #f5eee2;
}

.button--send:disabled {
  border-color: rgba(255, 255, 255, 0.06);
  background: rgba(255, 255, 255, 0.045);
  color: #62665f;
}

.suggestions {
  display: flex;
  gap: 5px;
  margin-top: 7px;
  overflow: hidden;
}

.suggestions button {
  min-width: 0;
  overflow: hidden;
  padding: 4px 7px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 20px;
  background: transparent;
  color: #646861;
  font-family: var(--serif);
  font-size: 9px;
  font-style: italic;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
  transition: border-color 180ms ease, color 180ms ease;
}

.suggestions button:hover {
  border-color: rgba(255, 255, 255, 0.14);
  color: #a09e96;
}

.rehearsal-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding-top: 11px;
}

.rehearse-button {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 0;
  border: 0;
  background: transparent;
  color: #b9b2a6;
  font-family: var(--serif);
  font-size: 11px;
  font-style: italic;
  cursor: pointer;
  transition: color 180ms ease;
}

.rehearse-button:hover {
  color: var(--amber-bright);
}

.rehearse-button__icon {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 14px;
}

.rehearse-button__icon i {
  display: block;
  width: 2px;
  height: 5px;
  border-radius: 2px;
  background: var(--amber);
  animation: equalizer 1.7s ease-in-out infinite;
}

.rehearse-button__icon i:nth-child(2) {
  height: 10px;
  animation-delay: -0.5s;
}

.rehearse-button__icon i:nth-child(3) {
  height: 7px;
  animation-delay: -1s;
}

.rehearsal-bar p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: #5f635d;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.live-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 6px rgba(145, 201, 192, 0.6);
}

.workbench {
  display: flex;
  min-width: 0;
  flex-direction: column;
  padding: 31px 25px 21px;
  border-left: 1px solid var(--line);
  background: linear-gradient(200deg, rgba(255, 255, 255, 0.022), transparent 40%);
}

.workbench__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.workbench__header h2 {
  margin: 4px 0 0;
  font-family: var(--serif);
  font-size: 26px;
  font-weight: 400;
  letter-spacing: -0.03em;
}

.receipt-count {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: #888b83;
  font-family: var(--mono);
  font-size: 9px;
}

.latest-receipt {
  position: relative;
  margin-top: 20px;
  padding: 18px 17px 14px;
  overflow: hidden;
  border-radius: 3px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.4), transparent 35%),
    var(--paper);
  color: var(--paper-ink);
  box-shadow: 0 14px 32px rgba(0, 0, 0, 0.2);
  animation: receipt-change 500ms ease both;
}

.latest-receipt::before,
.latest-receipt::after {
  position: absolute;
  right: 9px;
  left: 9px;
  height: 5px;
  content: "";
  opacity: 0.13;
  background: repeating-linear-gradient(90deg, transparent 0 4px, #352f27 4px 5px);
}

.latest-receipt::before {
  top: 0;
}

.latest-receipt::after {
  bottom: 0;
}

.receipt-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: #837b6d;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.latest-receipt > p {
  margin: 17px 0 18px;
  font-family: var(--serif);
  font-size: clamp(16px, 1.28vw, 19px);
  line-height: 1.38;
  letter-spacing: -0.012em;
}

.receipt-signature {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #9b9284;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.receipt-signature__line {
  height: 1px;
  flex: 1;
  background: rgba(66, 58, 49, 0.18);
}

.receipt-signature i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #b57b4a;
}

.receipt-stream {
  min-height: 95px;
  margin-top: 24px;
  flex: 1;
  overflow: hidden;
}

.section-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--line);
  color: #868a82;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.section-label button {
  padding: 0;
  border: 0;
  background: transparent;
  color: #5d615b;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
}

.section-label button:hover {
  color: #a5a59d;
}

.receipt-stream ol {
  display: flex;
  max-height: 205px;
  margin: 0;
  padding: 0;
  flex-direction: column;
  overflow-y: auto;
  list-style: none;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.12) transparent;
}

.receipt-stream li {
  position: relative;
  display: grid;
  grid-template-columns: 8px 1fr auto;
  gap: 8px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.055);
  color: #898c84;
  animation: quiet-arrive 450ms ease both;
}

.receipt-stream li::before {
  width: 4px;
  height: 4px;
  margin-top: 4px;
  content: "";
  border-radius: 50%;
  background: var(--stream-color, #858981);
}

.receipt-stream li[data-kind="question"] {
  --stream-color: var(--teal);
}

.receipt-stream li[data-kind="constraint"] {
  --stream-color: var(--amber);
}

.receipt-stream li[data-kind="refusal"] {
  --stream-color: var(--coral);
}

.receipt-stream li[data-kind="memory"] {
  --stream-color: var(--lilac);
}

.receipt-stream li[data-kind="world"] {
  --stream-color: #c7bda9;
}

.receipt-stream li p {
  margin: 0;
  overflow: hidden;
  color: #8e9088;
  font-size: 9px;
  line-height: 1.4;
  text-overflow: ellipsis;
}

.receipt-stream li time {
  color: #555a54;
  font-family: var(--mono);
  font-size: 7px;
  white-space: nowrap;
}

.empty-stream {
  display: block !important;
  padding-top: 15px !important;
  color: #5f635d !important;
  font-family: var(--serif);
  font-style: italic;
}

.empty-stream::before {
  display: none;
}

.handoff-card {
  margin-top: 18px;
  padding: 14px 14px 12px;
  border: 1px solid rgba(145, 201, 192, 0.14);
  border-radius: 9px;
  background:
    linear-gradient(135deg, rgba(145, 201, 192, 0.06), transparent 60%),
    rgba(255, 255, 255, 0.012);
}

.handoff-card__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.text-button {
  padding: 0;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.18);
  background: transparent;
  color: #888b83;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  line-height: 1.8;
  text-transform: uppercase;
  cursor: pointer;
}

.text-button:hover {
  color: var(--ink);
}

.handoff-card p {
  min-height: 37px;
  margin: 11px 0 12px;
  color: #bbb8af;
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  line-height: 1.45;
}

.handoff-card__foot {
  display: flex;
  justify-content: space-between;
  color: #5c615a;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.app-footer {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  min-height: 35px;
  padding: 0 28px;
  border-top: 1px solid var(--line);
  color: #585c56;
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.footer-center {
  color: #525650;
}

.app-footer > :last-child {
  justify-self: end;
  color: #74776f;
}

.ledger-dialog {
  width: min(720px, calc(100% - 30px));
  max-height: calc(100vh - 40px);
  padding: 0;
  overflow: auto;
  border: 1px solid rgba(240, 233, 219, 0.18);
  border-radius: 18px;
  background: #121514;
  color: var(--ink);
  box-shadow: 0 35px 100px rgba(0, 0, 0, 0.7);
}

.ledger-dialog::backdrop {
  background: rgba(5, 7, 7, 0.78);
  backdrop-filter: blur(10px);
}

.ledger-dialog[open] {
  animation: dialog-in 300ms cubic-bezier(0.22, 1, 0.36, 1);
}

.ledger-card {
  padding: 28px;
  background:
    radial-gradient(circle at 90% 0%, rgba(145, 201, 192, 0.07), transparent 30%),
    linear-gradient(145deg, rgba(255, 255, 255, 0.022), transparent 45%);
}

.ledger-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.ledger-card__header h2 {
  margin: 7px 0 0;
  font-family: var(--serif);
  font-size: 34px;
  font-weight: 400;
  letter-spacing: -0.04em;
}

.icon-button--close {
  width: 34px;
  height: 34px;
}

.ledger-intro {
  max-width: 590px;
  margin: 16px 0 22px;
  color: #979990;
  font-family: var(--serif);
  font-size: 15px;
  line-height: 1.55;
}

.ledger-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.ledger-stats > div {
  display: flex;
  min-height: 71px;
  padding: 13px 16px;
  flex-direction: column;
  justify-content: space-between;
  border-right: 1px solid var(--line);
}

.ledger-stats > div:first-child {
  padding-left: 0;
}

.ledger-stats > div:last-child {
  padding-right: 0;
  border-right: 0;
}

.ledger-stats span {
  color: #6f736c;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ledger-stats strong {
  font-family: var(--serif);
  font-size: 21px;
  font-weight: 400;
}

.handoff-editor {
  display: block;
  margin-top: 23px;
}

.handoff-editor textarea {
  display: block;
  width: 100%;
  margin-top: 9px;
  padding: 13px 14px;
  resize: vertical;
  border: 1px solid var(--line);
  border-radius: 7px;
  outline: 0;
  background: rgba(3, 5, 5, 0.32);
  color: #d8d3c8;
  font-family: var(--serif);
  font-size: 16px;
  line-height: 1.48;
  transition: border-color 180ms ease;
}

.handoff-editor textarea:focus {
  border-color: rgba(145, 201, 192, 0.44);
}

.handoff-editor__foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 8px;
  color: #676b65;
  font-size: 9px;
}

.ledger-invariants {
  display: grid;
  grid-template-columns: 125px 1fr;
  gap: 18px;
  margin-top: 22px;
  padding: 17px 18px;
  border: 1px solid rgba(229, 173, 104, 0.12);
  border-radius: 8px;
  background: rgba(229, 173, 104, 0.035);
}

.ledger-invariants > span {
  color: #9d8c73;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ledger-invariants ol {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 0;
  counter-reset: invariant;
  list-style: none;
}

.ledger-invariants li {
  position: relative;
  padding-left: 20px;
  color: #989990;
  font-family: var(--serif);
  font-size: 12px;
  line-height: 1.4;
  counter-increment: invariant;
}

.ledger-invariants li::before {
  position: absolute;
  top: 2px;
  left: 0;
  content: "0" counter(invariant);
  color: #6d665b;
  font-family: var(--mono);
  font-size: 7px;
}

.ledger-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}

.button--dark {
  border-color: rgba(255, 255, 255, 0.08);
  background: var(--paper);
  color: var(--paper-ink);
}

.button--dark:hover {
  background: #f4ecdf;
}

.button--outline {
  border-color: var(--line);
}

.button--outline:hover {
  border-color: var(--line-strong);
  background: rgba(255, 255, 255, 0.04);
}

.button--danger {
  margin-left: auto;
  color: #a46e63;
}

.button--danger:hover {
  border-color: rgba(217, 134, 115, 0.25);
  background: rgba(217, 134, 115, 0.05);
  color: var(--coral);
}

.button--danger.is-confirming {
  border-color: rgba(217, 134, 115, 0.4);
  color: var(--coral);
}

.ledger-status {
  min-height: 15px;
  margin: 10px 0 0;
  color: #858981;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.05em;
}

.toast {
  position: fixed;
  z-index: 20;
  right: 26px;
  bottom: 26px;
  max-width: min(360px, calc(100% - 40px));
  padding: 12px 16px;
  border: 1px solid rgba(240, 233, 219, 0.15);
  border-radius: 8px;
  background: rgba(22, 25, 24, 0.96);
  color: #c9c5bb;
  font-family: var(--serif);
  font-size: 12px;
  line-height: 1.4;
  box-shadow: 0 15px 45px rgba(0, 0, 0, 0.4);
  opacity: 0;
  pointer-events: none;
  transform: translateY(10px);
  transition: opacity 220ms ease, transform 220ms ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.no-script {
  position: fixed;
  z-index: 30;
  right: 20px;
  bottom: 20px;
  left: 20px;
  padding: 16px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background: var(--night-soft);
  color: var(--ink);
  text-align: center;
}

@keyframes listening {
  0% { opacity: 0.55; transform: scale(0.7); }
  70%, 100% { opacity: 0; transform: scale(1.65); }
}

@keyframes slow-spin {
  to { transform: rotate(360deg); }
}

@keyframes orb-breathe {
  0%, 100% { opacity: 0.56; transform: scale(0.98); }
  50% { opacity: 0.9; transform: scale(1.04); }
}

@keyframes equalizer {
  0%, 100% { transform: scaleY(0.65); opacity: 0.62; }
  50% { transform: scaleY(1.1); opacity: 1; }
}

@keyframes node-arrive {
  from { opacity: 0; transform: translate(-50%, -50%) scale(0.82); }
  to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

@keyframes new-thought {
  0% { box-shadow: 0 0 0 0 currentColor; }
  100% { box-shadow: 0 0 0 15px transparent; }
}

@keyframes orbit-bloom {
  0% { opacity: 0.3; }
  35% { opacity: 0.9; }
  100% { opacity: 1; }
}

@keyframes rehearse-orb {
  0% { filter: brightness(1); transform: scale(1); }
  32% { filter: brightness(1.32); transform: scale(1.035); }
  100% { filter: brightness(1); transform: scale(1); }
}

@keyframes receipt-change {
  from { opacity: 0.45; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes quiet-arrive {
  from { opacity: 0; transform: translateY(3px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes dialog-in {
  from { opacity: 0; transform: translateY(8px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (max-width: 1240px) {
  .app-grid {
    grid-template-columns: 235px minmax(480px, 1fr) 282px;
  }

  .memory-rail {
    padding-right: 24px;
    padding-left: 24px;
  }

  .world-stage {
    padding-right: 22px;
    padding-left: 22px;
  }

  .workbench {
    padding-right: 20px;
    padding-left: 20px;
  }

  .kind {
    gap: 5px;
    padding-right: 5px;
    padding-left: 5px;
  }

  .kind__glyph {
    width: 20px;
    height: 20px;
  }

  .suggestions button:nth-child(3) {
    display: none;
  }
}

@media (max-width: 1020px) {
  .app-shell {
    min-height: calc(100vh - 20px);
    margin: 10px auto;
  }

  .topbar {
    grid-template-columns: 1fr auto;
  }

  .save-state {
    display: none;
  }

  .app-grid {
    grid-template-columns: 245px minmax(0, 1fr);
  }

  .memory-rail {
    grid-row: 1;
  }

  .world-stage {
    grid-row: 1;
  }

  .workbench {
    display: grid;
    grid-column: 1 / -1;
    grid-template-columns: minmax(250px, 0.75fr) minmax(260px, 1fr) minmax(250px, 0.8fr);
    gap: 22px;
    padding: 24px 28px;
    border-top: 1px solid var(--line);
    border-left: 0;
  }

  .workbench__header {
    display: none;
  }

  .latest-receipt,
  .receipt-stream,
  .handoff-card {
    margin-top: 0;
  }

  .receipt-stream {
    min-height: 0;
  }

  .receipt-stream ol {
    max-height: 150px;
  }

  .orbital-map {
    min-height: 300px;
  }

  .app-footer {
    grid-template-columns: 1fr auto;
  }

  .footer-center {
    display: none;
  }
}

@media (max-width: 760px) {
  .app-shell {
    width: calc(100% - 16px);
    margin: 8px auto;
    border-radius: 15px;
  }

  .topbar {
    min-height: 65px;
    padding: 0 14px;
  }

  .brand__mark {
    width: 29px;
    height: 29px;
  }

  .brand__mark::before {
    width: 36px;
