const html = fs.readFileSync(path.join(root, "index.html"), "utf8");
const appSource = fs.readFileSync(path.join(root, "app.js"), "utf8");
const css = fs.readFileSync(path.join(root, "styles.css"), "utf8");
const schema = JSON.parse(fs.readFileSync(path.join(root, "world-memory.schema.json"), "utf8"));
const manifest = JSON.parse(fs.readFileSync(path.join(root, "manifest.webmanifest"), "utf8"));
const packageJson = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
const serviceWorker = fs.readFileSync(path.join(root, "sw.js"), "utf8");

const MEMORY_KEY = "tendora.world.memory.v1";
const BACKUP_KEY = "tendora.world.memory.backup.v1";

class FakeStorage {
  constructor(seed) {
    this.values = new Map(Object.entries(seed || {}));
  }

  getItem(key) {
    return this.values.has(key) ? this.values.get(key) : null;
  }

  setItem(key, value) {
    this.values.set(key, String(value));
  }

  removeItem(key) {
    this.values.delete(key);
  }

  dump() {
    return Object.fromEntries(this.values);
  }
}

class FakeClassList {
  constructor() {
    this.values = new Set();
  }

  add(...names) {
    names.forEach((name) => this.values.add(name));
  }

  remove(...names) {
    names.forEach((name) => this.values.delete(name));
  }

  toggle(name, force) {
    const shouldAdd = force === undefined ? !this.values.has(name) : Boolean(force);
    if (shouldAdd) {
      this.values.add(name);
    } else {
      this.values.delete(name);
    }
    return shouldAdd;
  }

  contains(name) {
    return this.values.has(name);
  }
}

class FakeElement {
  constructor(tagName, id, document) {
    this.tagName = String(tagName || "div").toUpperCase();
    this.id = id || "";
    this.ownerDocument = document;
    this.children = [];
    this.parentNode = null;
    this.dataset = {};
    this.style = {};
    this.classList = new FakeClassList();
    this.attributes = {};
    this.listeners = new Map();
    this.value = "";
    this.disabled = false;
    this.hidden = false;
    this.files = null;
    this.tabIndex = 0;
    this.title = "";
    this.open = false;
    this.offsetWidth = 640;
    this._textContent = "";
  }

  set textContent(value) {
    this._textContent = String(value);
    this.children = [];
  }

  get textContent() {
    return this._textContent;
  }

  append(...nodes) {
    nodes.forEach((node) => {
      if (node && typeof node === "object") {
        node.parentNode = this;
        this.children.push(node);
      }
    });
  }

  appendChild(node) {
    this.append(node);
    return node;
  }

  replaceChildren(...nodes) {
    this.children.forEach((child) => {
      child.parentNode = null;
    });
    this.children = [];
    this.append(...nodes);
  }

  remove() {
    if (this.parentNode) {
      this.parentNode.children = this.parentNode.children.filter((child) => child !== this);
      this.parentNode = null;
    }
  }

  addEventListener(type, listener) {
    if (!this.listeners.has(type)) {
      this.listeners.set(type, []);
    }
    this.listeners.get(type).push(listener);
  }

  async dispatch(type, details) {
    const event = Object.assign({
      type: type,
      target: this,
      key: "",
      shiftKey: false,
      preventDefault: function () {
        this.defaultPrevented = true;
      }
    }, details || {});
    const results = (this.listeners.get(type) || []).map((listener) => listener(event));
    await Promise.all(results);
    return event;
  }

  click() {
    this.dispatch("click");
  }

  setAttribute(name, value) {
    this.attributes[name] = String(value);
    if (name === "open") {
      this.open = true;
    }
  }

  getAttribute(name) {
    return Object.prototype.hasOwnProperty.call(this.attributes, name) ? this.attributes[name] : null;
  }

  removeAttribute(name) {
    delete this.attributes[name];
    if (name === "open") {
      this.open = false;
    }
  }

  showModal() {
    this.open = true;
  }

  close() {
    this.open = false;
    this.dispatch("close");
  }

  focus() {
    if (this.ownerDocument) {
      this.ownerDocument.activeElement = this;
    }
  }

  setSelectionRange() {}

  getBoundingClientRect() {
    return { x: 0, y: 0, width: 640, height: 380, top: 0, left: 0, right: 640, bottom: 380 };
  }

  querySelectorAll(selector) {
    const found = [];
    const visit = function (node) {
      node.children.forEach((child) => {
        if (matchesComposite(child, selector)) {
          found.push(child);
        }
        visit(child);
      });
    };
    visit(this);
    return found;
  }

  querySelector(selector) {
    return this.querySelectorAll(selector)[0] || null;
  }
}

function matchesSimple(element, selector) {
  if (!element || !selector) {
    return false;
  }
  const tag = selector.match(/^([a-zA-Z][\w-]*)/);
  if (tag && element.tagName !== tag[1].toUpperCase()) {
    return false;
  }
  const id = selector.match(/#([\w-]+)/);
  if (id && element.id !== id[1]) {
    return false;
  }
  const classes = Array.from(selector.matchAll(/\.([\w-]+)/g), (match) => match[1]);
  if (classes.some((name) => !element.classList.contains(name))) {
    return false;
  }
  const data = selector.match(/\[data-([\w-]+)="([^"]+)"\]/);
  if (data) {
    const key = data[1].replace(/-([a-z])/g, (_, letter) => letter.toUpperCase());
    if (element.dataset[key] !== data[2]) {
      return false;
    }
  }
  return Boolean(tag || id || classes.length || data);
}

function matchesComposite(element, selector) {
  const parts = selector.trim().split(/\s+/);
  if (!matchesSimple(element, parts[parts.length - 1])) {
    return false;
  }
  let ancestor = element.parentNode;
  for (let index = parts.length - 2; index >= 0; index -= 1) {
    while (ancestor && !matchesSimple(ancestor, parts[index])) {
      ancestor = ancestor.parentNode;
    }
    if (!ancestor) {
      return false;
    }
    ancestor = ancestor.parentNode;
  }
  return true;
}

function createHarness(seedStorage) {
  const storage = new FakeStorage(seedStorage);
  const byId = new Map();
  const timers = [];
  let timerId = 0;
  let uuidId = 0;

  const document = {
    activeElement: null,
    visibilityState: "visible",
    listeners: new Map(),
    body: null,
    createElement(tagName) {
      return new FakeElement(tagName, "", document);
    },
    getElementById(id) {
      return byId.get(id) || null;
    },
    querySelectorAll(selector) {
      return document.body.querySelectorAll(selector);
    },
    querySelector(selector) {
      return document.body.querySelector(selector);
    },
    addEventListener(type, listener) {
      if (!document.listeners.has(type)) {
        document.listeners.set(type, []);
      }
      document.listeners.get(type).push(listener);
    }
  };

  document.body = new FakeElement("body", "", document);
  const ids = Array.from(html.matchAll(/\bid="([^"]+)"/g), (match) => match[1]);
  ids.forEach((id) => {
    const element = new FakeElement("div", id, document);
    byId.set(id, element);
    document.body.append(element);
  });

  ["coherence", "wonder", "care"].forEach((metricName) => {
    const metric = new FakeElement("div", "", document);
    const strong = new FakeElement("strong", "", document);
    const track = new FakeElement("div", "", document);
    const trackSpan = new FakeElement("span", "", document);
    metric.dataset.metric = metricName;
    metric.classList.add("metric");
    track.classList.add("metric__track");
    track.append(trackSpan);
    metric.append(strong, track);
    document.body.append(metric);
  });

  ["question", "constraint", "refusal", "memory"].forEach((kind) => {
    const button = new FakeElement("button", "", document);
    button.classList.add("kind");
    button.dataset.kind = kind;
    document.body.append(button);
  });

  const windowObject = {
    localStorage: storage,
    crypto: {
      randomUUID() {
        uuidId += 1;
        return "00000000-0000-4000-8000-" + String(uuidId).padStart(12, "0");
      }
    },
    location: { protocol: "file:" },
    setTimeout(callback, delay) {
      timerId += 1;
      timers.push({ id: timerId, callback, delay });
      return timerId;
    },
    clearTimeout(id) {
      const timer = timers.find((item) => item.id === id);
      if (timer) {
        timer.cancelled = true;
      }
    },
    setInterval() {
      return ++timerId;
    },
    addEventListener() {}
  };

  class ResizeObserver {
    observe() {}
  }

  const sandbox = {
    window: windowObject,
    document: document,
    navigator: {},
    ResizeObserver: ResizeObserver,
    console: console,
    Blob: Blob,
    URL: {
      createObjectURL() {
        return "blob:tendora";
      },
      revokeObjectURL() {}
    },
    setTimeout: windowObject.setTimeout,
    clearTimeout: windowObject.clearTimeout,
    setInterval: windowObject.setInterval
  };
  vm.createContext(sandbox);
  vm.runInContext(appSource, sandbox, { filename: "app.js" });

  return { byId, document, storage, timers, windowObject };
}

function readStoredMemory(storage) {
  return JSON.parse(storage.getItem(MEMORY_KEY));
}

test("material contract is complete and internally linked", function () {
  const required = [
    "index.html",
    "styles.css",
    "app.js",
    "favicon.svg",
    "manifest.webmanifest",
    "sw.js",
    "serve.mjs",
    "world-memory.schema.json",
    "README.md",
    "CONTINUITY.md"
  ];
  required.forEach((file) => {
    assert.equal(fs.existsSync(path.join(root, file)), true, file + " must exist");
  });

  const ids = Array.from(html.matchAll(/\bid="([^"]+)"/g), (match) => match[1]);
  assert.equal(new Set(ids).size, ids.length, "HTML IDs must be unique");
  const requestedIds = Array.from(appSource.matchAll(/getElementById\("([^"]+)"\)/g), (match) => match[1]);
  requestedIds.forEach((id) => assert.ok(ids.includes(id), "app.js expects #" + id));

  assert.match(html, /<link rel="stylesheet" href="styles.css">/);
  assert.match(html, /<script src="app.js" defer><\/script>/);
  assert.match(html, /href="manifest.webmanifest"/);
  assert.equal(css.split("{").length, css.split("}").length, "CSS braces must balance");
  assert.doesNotThrow(() => new Function(appSource));
  assert.doesNotThrow(() => new Function(serviceWorker));
});

test("portable schema and package contract agree", function () {
  assert.equal(schema.$schema, "https://json-schema.org/draft/2020-12/schema");
  assert.equal(schema.properties.format.const, "tendora-world-memory");
  assert.equal(schema.properties.schemaVersion.const, 1);
  assert.equal(schema.$defs.thought.properties.kind.$ref, "#/$defs/gestureKind");
  assert.deepEqual(schema.$defs.gestureKind.enum, ["question", "constraint", "refusal", "memory"]);
  assert.equal(manifest.start_url, "./index.html");
  assert.equal(manifest.display, "standalone");
  assert.equal(packageJson.private, true);
  assert.equal(packageJson.scripts.test, "node tests/world.test.cjs");
  assert.match(serviceWorker, /\.\/world-memory\.schema\.json/);
});

test("the world boots, takes a gesture, rehearses, and persists", function () {
  const harness = createHarness();
  const initial = readStoredMemory(harness.storage);
  assert.equal(initial.thoughts.length, 4);
  assert.equal(initial.receipts.length, 5);
  assert.equal(harness.byId.get("thoughtNodes").children.length, 4);
  assert.equal(harness.document.querySelector('[data-metric="coherence"]').querySelector("strong").textContent, "67");

  const constraintButton = harness.document.querySelector('.kind[data-kind="constraint"]');
  constraintButton.click();
  assert.equal(constraintButton.getAttribute("aria-checked"), "true");
  const input = harness.byId.get("thoughtInput");
  input.value = "Every memory must remain legible to a future hand.";
  input.dispatch("input");
  assert.equal(harness.byId.get("addThought").disabled, false);
  harness.byId.get("addThought").click();

  const afterGesture = readStoredMemory(harness.storage);
  assert.equal(afterGesture.thoughts.length, 5);
  assert.equal(afterGesture.thoughts[4].kind, "constraint");
  assert.match(harness.byId.get("latestReply").textContent, /future hand/);
  assert.equal(harness.byId.get("latestReceipt").dataset.kind, "constraint");
  assert.equal(harness.byId.get("fragmentCount").textContent, "5 fragments held");

  harness.byId.get("rehearseButton").click();
  const afterRehearsal = readStoredMemory(harness.storage);
  assert.equal(afterRehearsal.cycle, 1);
  assert.equal(harness.byId.get("cycleLabel").textContent, "002");
  assert.equal(harness.byId.get("latestReceipt").dataset.kind, "world");
  assert.ok(afterRehearsal.receipts.length > afterGesture.receipts.length);
});

test("handoff notes and portable memory return without losing gestures", async function () {
  const harness = createHarness();
  harness.byId.get("openLedger").click();
  assert.equal(harness.byId.get("ledgerDialog").open, true);
  const handoff = harness.byId.get("handoffInput");
  handoff.value = "A later hand should test every door before trusting the map.";
  handoff.dispatch("input");
  harness.byId.get("saveHandoff").click();
  assert.equal(readStoredMemory(harness.storage).handoff, handoff.value);

  const exportedState = readStoredMemory(harness.storage);
  const portable = {
    format: "tendora-world-memory",
    schemaVersion: 1,
    exportedAt: new Date().toISOString(),
    world: exportedState
  };
  const fileElement = harness.byId.get("memoryFile");
  fileElement.files = [{
    size: JSON.stringify(portable).length,
    text: async function () {
      return JSON.stringify(portable);
    }
  }];
  await fileElement.dispatch("change");

  const returned = readStoredMemory(harness.storage);
  assert.equal(returned.handoff, handoff.value);
  assert.equal(returned.thoughts.length, 4);
  assert.match(harness.byId.get("latestReply").textContent, /returned from outside the room/);
  assert.ok(harness.storage.getItem(BACKUP_KEY));
});

test("a long absence becomes quiet rehearsal and corrupt data is backed up", function () {
  const first = createHarness();
  const oldState = readStoredMemory(first.storage);
  oldState.lastSeenAt = new Date(Date.now() - 6 * 60_000).toISOString();
  oldState.cycle = 3;
  const second = createHarness({ [MEMORY_KEY]: JSON.stringify(oldState) });
  const resumed = readStoredMemory(second.storage);
  assert.ok(resumed.cycle >= 6, "quiet cycles should be added after absence");
  assert.match(resumed.receipts[0].text, /quiet|world|rooms/i);

  const corrupt = createHarness({ [MEMORY_KEY]: "{not-json" });
  assert.equal(corrupt.storage.getItem(BACKUP_KEY), "{not-json");
  const recovered = readStoredMemory(corrupt.storage);
  assert.equal(recovered.thoughts.length, 4);
  assert.equal(recovered.schemaVersion, 1);
});

test("reset preserves the previous world in backup and restores the inherited present", function () {
  const harness = createHarness();
  harness.byId.get("thoughtInput").value = "A gesture that will survive in backup.";
  harness.byId.get("thoughtInput").dispatch("input");
  harness.byId.get("addThought").click();
  const changed = readStoredMemory(harness.storage);
  assert.equal(changed.thoughts.length, 5);

  harness.byId.get("resetWorld").click();
  harness.byId.get("resetWorld").click();
  const reset = readStoredMemory(harness.storage);
  const backup = JSON.parse(harness.storage.getItem(BACKUP_KEY));
  assert.equal(reset.thoughts.length, 4);
  assert.equal(reset.cycle, 0);
  assert.equal(backup.thoughts.length, changed.thoughts.length);
  assert.match(backup.thoughts[4].text, /survive in backup/);
});

test("a memory from a later schema is refused without replacing the present", async function () {
  const harness = createHarness();
  const before = harness.storage.getItem(MEMORY_KEY);
  const futureMemory = JSON.parse(before);
  futureMemory.schemaVersion = 2;
  const fileElement = harness.byId.get("memoryFile");
  fileElement.files = [{
    size: JSON.stringify(futureMemory).length,
    text: async function () {
      return JSON.stringify(futureMemory);
    }
  }];

  await fileElement.dispatch("change");
  assert.equal(harness.storage.getItem(MEMORY_KEY), before);
  assert.match(harness.byId.get("ledgerStatus").textContent, /later schema/);
});

